// ===== taller boards =====
// Every board gets extra empty rows (split above and below) so it fills a phone screen. The board is the same
// size for every player, so the scores stay fair. The puzzle itself is unchanged; the new rows are free space
// for later levels.
function padLevel(L) {
  {
    if (L.padded) return L;
    const H = Math.max(L.h, Math.round(L.w * 1.9)), extra = H - L.h; if (extra <= 0) { L.padded = true; return L; }
    // a Heli Bot flies up to the top edge, so those boards keep their top edge and grow downward only
    const usesUp = JSON.stringify([L.sol, L.fixed || [], L.inv]).includes('helibot');
    const top = usesUp ? 0 : Math.floor(extra / 2), bot = extra - top, empty = '.'.repeat(L.w);
    L.map = Array(top).fill(empty).concat(L.map, Array(bot).fill(empty)); L.h = H;
    const sh = a => a && a.map(o => { const q = o.slice(); q[2] += top; return q; });
    L.sol = sh(L.sol); if (L.fixed) L.fixed = sh(L.fixed);
    const fix = t => typeof t === 'string' ? t.replace(/\brow (\d+)/g, (m, n) => 'row ' + (+n + top)) : t;
    for (const k of ['hint', 'nudge', 'trick', 'intro']) L[k] = fix(L[k]);
    if (L.steps) L.steps = L.steps.map(fix);
    L.padded = true;
  }
  return L;
}
LEVELS.forEach(padLevel);
if (typeof module !== 'undefined') module.exports = { LEVELS, padLevel };
